/* eslint-disable */

/**
 * Manages the tracking, matching, and lifecycle of video frame buffers across a session.
 */
export class BufferPlanner {
    free(): void;
    [Symbol.dispose](): void;
    evaluateTarget(target_roi_val: any, timestamp: number, active_buffers_val: any): any;
    constructor(config_val: any);
    poll(active_buffers_val: any, current_time: number, mode_val: any, has_state: boolean, flush: boolean): any;
}

/**
 * A thread-safe, stateful session object for processing continuous frame data natively across FFI and Wasm.
 */
export class Session {
    free(): void;
    [Symbol.dispose](): void;
    constructor(config_val: any);
    processJs(input_val: any, mode_val: any): any;
    reset(): void;
}

export function calculateRoi(face_val: any, method_val: any, detector_val: any, container_w: number | null | undefined, container_h: number | null | undefined, force_even: boolean): any;

export function computeBufferConfig(config_val: any): any;

export function getVitalInfo(vital_id: string): any;

export type InitInput = RequestInfo | URL | Response | BufferSource | WebAssembly.Module;

export interface InitOutput {
    readonly memory: WebAssembly.Memory;
    readonly __wbg_bufferplanner_free: (a: number, b: number) => void;
    readonly __wbg_session_free: (a: number, b: number) => void;
    readonly bufferplanner_evaluateTarget: (a: number, b: number, c: number, d: number, e: number) => void;
    readonly bufferplanner_new_js: (a: number, b: number) => void;
    readonly bufferplanner_poll: (a: number, b: number, c: number, d: number, e: number, f: number, g: number) => void;
    readonly calculateRoi: (a: number, b: number, c: number, d: number, e: number, f: number, g: number) => void;
    readonly computeBufferConfig: (a: number, b: number) => void;
    readonly getVitalInfo: (a: number, b: number) => number;
    readonly session_new_js: (a: number, b: number) => void;
    readonly session_processJs: (a: number, b: number, c: number, d: number) => void;
    readonly session_reset: (a: number) => void;
    readonly __wbindgen_export: (a: number, b: number) => number;
    readonly __wbindgen_export2: (a: number, b: number, c: number, d: number) => number;
    readonly __wbindgen_export3: (a: number) => void;
    readonly __wbindgen_add_to_stack_pointer: (a: number) => number;
}

export type SyncInitInput = BufferSource | WebAssembly.Module;

/**
 * Instantiates the given `module`, which can either be bytes or
 * a precompiled `WebAssembly.Module`.
 *
 * @param {{ module: SyncInitInput }} module - Passing `SyncInitInput` directly is deprecated.
 *
 * @returns {InitOutput}
 */
export function initSync(module: { module: SyncInitInput } | SyncInitInput): InitOutput;

/**
 * If `module_or_path` is {RequestInfo} or {URL}, makes a request and
 * for everything else, calls `WebAssembly.instantiate` directly.
 *
 * @param {{ module_or_path: InitInput | Promise<InitInput> }} module_or_path - Passing `InitInput` directly is deprecated.
 *
 * @returns {Promise<InitOutput>}
 */
export default function __wbg_init (module_or_path?: { module_or_path: InitInput | Promise<InitInput> } | InitInput | Promise<InitInput>): Promise<InitOutput>;
